#!/usr/bin/env python3
# Generated by Phase: IMPLEMENT | Feature: EVOL-043
"""gate — the framework's one reader. Every hook, gate and pre-flight asks it; none re-derives.

  gate.py key <dotted>                  print a config key (config/quality.json); fail-closed with --required
  gate.py context                       meta | downstream
  gate.py laws [--json]                 the law index (universal + project) as parsed
  gate.py applicable [--phase P] [--scope S] [--change-type T] [--command C] [--framework F…]
                     [--paths p…] [--format json|rollcall] [--feature ID]
  gate.py digest --paths p… [--budget N]     the slice of law governing paths, within budget
  gate.py deliver --path p [--session SID]   PreToolUse payload (hookSpecificOutput.additionalContext), deduped per session
  gate.py snapshot-sections [--profile lite|full]   law index + families (+ bodies) for the snapshot generator
  gate.py budget                        run every producer at worst case; exit 1 on overflow or missing key
  gate.py retired-terms                 the retired-vocabulary ratchet; exit 1 on a hit

Exit: 0 ok · 1 gate red · 2 the tool could not do its job (plain language, LAW-08).
"""
from __future__ import annotations

import argparse
import hashlib
import json
import os
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent))
from gates import budget as budget_mod, corpus, retired  # noqa: E402
from gates.common import GateFault, context, key, repo_root, rules_root  # noqa: E402


def cmd_key(repo, a):
    v = key(repo, a.dotted, required=a.required)
    print(json.dumps(v) if not isinstance(v, str) else v)
    return 0


def cmd_laws(repo, a):
    out = corpus.laws(repo)
    if a.json:
        print(json.dumps(out, indent=2, ensure_ascii=False))
    else:
        for group in ("universal", "project"):
            for l in out[group]:
                print(f"{l['id']}  {l['title']} — {l['sentence']}  [{l['body'] or '?'}]")
    return 0


def _ctx(a) -> dict:
    return {k: v for k, v in {"phase": a.phase, "scope": a.scope, "change_type": a.change_type, "command": a.command,
                              "framework": a.framework or [], "agent": getattr(a, "agent", None)}.items() if v}


def cmd_applicable(repo, a):
    res = corpus.applicable(repo, _ctx(a), a.paths or None)
    print(json.dumps(res, indent=2, ensure_ascii=False) if a.format == "json" else corpus.rollcall(res, a.command or "", a.feature or ""))
    return 0


def cmd_digest(repo, a):
    b = a.budget or key(repo, "budgets.pre_edit", required=True)
    print(corpus.digest(repo, a.paths, int(b)))
    return 0


def cmd_deliver(repo, a):
    """Stdout = the JSON envelope a PreToolUse hook must print for its context to reach the model."""
    b = key(repo, "budgets.pre_edit", required=True)
    rel = a.path
    try:
        rel = str(Path(a.path).resolve().relative_to(repo))
    except ValueError:
        pass
    text = corpus.digest(repo, [rel], int(b))
    sid = "".join(ch for ch in (a.session or "") if ch.isalnum() or ch in "-_")
    marker = repo / ".claude/state" / f"governance-delivered-{sid or 'session'}.txt"
    fingerprint = hashlib.sha256(text.encode()).hexdigest()[:16]
    seen = set()
    try:
        if marker.is_file():
            seen = set(marker.read_text(encoding="utf-8").split())
    except OSError:
        seen = set()
    if fingerprint in seen:
        text = f'<governance-at-edit paths="{rel}" delivered="earlier-this-session" fingerprint="{fingerprint}" />'
    else:
        try:
            marker.parent.mkdir(parents=True, exist_ok=True)
            with marker.open("a", encoding="utf-8") as fh:
                fh.write(fingerprint + "\n")
        except OSError:
            pass
    print(json.dumps({"hookSpecificOutput": {"hookEventName": "PreToolUse", "additionalContext": text}}))
    return 0


def cmd_snapshot_sections(repo, a):
    law = corpus.laws(repo)
    cat = corpus.catalog(repo)
    out = ["## Law Index", f"> Source: {'docs/constitution.md' if context(repo) == 'downstream' else 'constitution template'} "
           "(project laws) — one sentence, one body, its records. Universal laws live in CLAUDE.md § Governance Rules.", ""]
    for l in law["project"]:
        out += [f"### [{l['id']}] {l['title']}", f"> {l['sentence']}", f"Body: `{l['body'] or 'inline'}` · Records: {', '.join('`' + r + '`' for r in l['records']) or '—'}", ""]
    if not law["project"]:
        out.append("> (no project law index found)\n")
    out += ["## Defect Families", f"> Source: {cat['path'] or 'defect-prevention.md (absent)'} § Families. Defect classes are delivered at the point of edit by the pre-edit hook; read the catalog by id.", ""]
    if cat["families"]:
        out += ["| Family | Surface | Invariant |", "|---|---|---|"]
        out += [f"| `{f['name']}` | {', '.join('`' + g + '`' for g in f['surface'])} | {f['invariant']} |" for f in cat["families"]]
    else:
        out.append("> (no families)")
    if a.profile == "full":
        out += ["", "## Law Bodies (full profile — never injected)", ""]
        for l in law["project"] + law["universal"]:
            p, heading, quoted = corpus.body_section(repo, l)
            out.append(f"### [{l['id']}] → {l['body'] or 'inline'}" + ("" if heading else "  (body section not found)"))
            if p and p.is_file() and heading:
                text = p.read_text(encoding="utf-8", errors="replace").splitlines()
                start = text.index(heading)
                body = []
                for ln in text[start + 1:]:
                    if ln.startswith("## "):
                        break
                    body.append(ln)
                out += body
            out.append("")
        out += ["## Defect Classes (full profile)", "", "| DC | Family | Invariant | Gate | Paths |", "|---|---|---|---|---|"]
        out += [f"| {d['id']} | `{d['family']}` | {d['invariant']} | {d['gate']} | {', '.join(d['paths'])} |" for d in cat["dcs"]]
    print("\n".join(out))
    return 0


def cmd_budget(repo, a):
    rows = budget_mod.measure(repo)
    print(budget_mod.render(rows))
    bad = [k for k, r in rows.items() if not r["ok"]]
    if bad:
        print(f"budget: OVERFLOW at {', '.join(bad)} — shrink the producer or raise the key in config/quality.json (with its record).", file=sys.stderr)
        return 1
    print("budget: ok — every producer within its key.")
    return 0


def cmd_retired(repo, a):
    hits = retired.scan(repo)
    print(retired.render(hits))
    return 1 if hits else 0


def build_parser():
    ap = argparse.ArgumentParser(prog="gate.py", description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--repo", default=None)
    sub = ap.add_subparsers(dest="cmd", required=True)
    p = sub.add_parser("key"); p.add_argument("dotted"); p.add_argument("--required", action="store_true"); p.set_defaults(fn=cmd_key)
    p = sub.add_parser("context"); p.set_defaults(fn=lambda r, a: print(context(r)) or 0)
    p = sub.add_parser("laws"); p.add_argument("--json", action="store_true"); p.set_defaults(fn=cmd_laws)
    p = sub.add_parser("applicable")
    for opt in ("--phase", "--scope", "--change-type", "--command", "--feature", "--agent"):
        p.add_argument(opt, default=None)
    p.add_argument("--framework", nargs="*", default=None); p.add_argument("--paths", nargs="*", default=None)
    p.add_argument("--format", choices=("json", "rollcall"), default="rollcall"); p.set_defaults(fn=cmd_applicable)
    p = sub.add_parser("digest"); p.add_argument("--paths", nargs="+", required=True); p.add_argument("--budget", type=int, default=None); p.set_defaults(fn=cmd_digest)
    p = sub.add_parser("deliver"); p.add_argument("--path", required=True); p.add_argument("--session", default=""); p.set_defaults(fn=cmd_deliver)
    p = sub.add_parser("snapshot-sections"); p.add_argument("--profile", choices=("lite", "full"), default="lite"); p.set_defaults(fn=cmd_snapshot_sections)
    p = sub.add_parser("budget"); p.set_defaults(fn=cmd_budget)
    p = sub.add_parser("retired-terms"); p.set_defaults(fn=cmd_retired)
    return ap


def main(argv=None) -> int:
    a = build_parser().parse_args(argv)
    repo = Path(a.repo).resolve() if a.repo else repo_root()
    try:
        return a.fn(repo, a)
    except GateFault as e:
        print(f"gate: {e}", file=sys.stderr)
        return 2
    except Exception as e:  # LAW-08: never a raw trace unless asked
        if os.environ.get("GATE_DEBUG") == "1":
            raise
        print(f"gate: the tool could not do its job ({type(e).__name__}: {e}). Set GATE_DEBUG=1 for the trace.", file=sys.stderr)
        return 2


if __name__ == "__main__":
    sys.exit(main())
